#![allow(clippy::too_many_lines)]

use crate::*;

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct AlgebraContract {
    schema: String,
    exhaustive_threshold_bound: u16,
    truth_order: Vec<String>,
    attenuation_acceptance: String,
    attenuation_dimensions: Vec<AlgebraDimension>,
    threshold: ThresholdContract,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct AlgebraDimension {
    rust: String,
    lean: String,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct ThresholdContract {
    authorized: String,
    indeterminate: String,
    denied: String,
}

pub(crate) fn load_algebra_contract() -> Result<AlgebraContract, String> {
    let path = root().join("formal/algebra-contract-v1.toml");
    let contract: AlgebraContract = toml::from_str(
        &fs::read_to_string(&path)
            .map_err(|error| format!("could not read {}: {error}", path.display()))?,
    )
    .map_err(|error| format!("invalid algebra contract {}: {error}", path.display()))?;
    if contract.schema != "auths-proof-algebra-contract/v1"
        || contract.exhaustive_threshold_bound == 0
        || contract.truth_order != ["denied", "indeterminate", "authorized"]
        || contract.attenuation_acceptance != "all"
        || contract.attenuation_dimensions.is_empty()
        || contract.threshold.authorized != "authorized >= required"
        || contract.threshold.indeterminate
            != "authorized < required && authorized + indeterminate >= required"
        || contract.threshold.denied != "authorized + indeterminate < required"
    {
        return Err("unsupported algebra contract semantics".to_owned());
    }
    let rust_names: BTreeSet<_> = contract
        .attenuation_dimensions
        .iter()
        .map(|dimension| dimension.rust.as_str())
        .collect();
    let lean_names: BTreeSet<_> = contract
        .attenuation_dimensions
        .iter()
        .map(|dimension| dimension.lean.as_str())
        .collect();
    if rust_names.len() != contract.attenuation_dimensions.len()
        || lean_names.len() != contract.attenuation_dimensions.len()
    {
        return Err("algebra contract dimension names must be unique".to_owned());
    }
    Ok(contract)
}

pub(crate) fn dimension_description(name: &str) -> &'static str {
    match name {
        "root_preserved" => "the trust root is preserved",
        "depth_decreases" => "delegation depth strictly decreases",
        "profile_attenuates" => "the selected profile does not widen",
        "permissions_attenuate" => "permissions do not widen",
        "validity_attenuates" => "the validity window does not widen",
        "audiences_attenuate" => "audiences do not widen",
        "action_constraint_attenuates" => "the action-body constraint does not widen",
        "budget_attenuates" => "the budget ceiling does not widen",
        "status_attenuates" => "status requirements do not weaken",
        "assurance_attenuates" => "assurance requirements do not weaken",
        "extensions_attenuate" => {
            "every critical extension satisfies its identifier's attenuation law"
        }
        _ => "the declared authority dimension attenuates",
    }
}

pub(crate) fn render_rust_algebra(contract: &AlgebraContract) -> Result<String, String> {
    macro_rules! line {
        ($output:expr, $($argument:tt)*) => {
            writeln!($output, $($argument)*)
                .map_err(|_| "could not render generated Rust algebra".to_owned())?
        };
    }

    let mut output = String::new();
    output.push_str(
        "// @generated by `cargo xtask formal --update`; DO NOT EDIT.\n\n\
         /// Versioned source contract used to generate this module.\n",
    );
    line!(
        output,
        "pub const CONTRACT_SCHEMA: &str = {:?};",
        contract.schema
    );
    output.push_str("\n/// Exhaustive default-deployment threshold bound.\n");
    line!(
        output,
        "pub const EXHAUSTIVE_THRESHOLD_BOUND: u16 = {};",
        contract.exhaustive_threshold_bound
    );
    output.push_str(
        "\n/// Closed three-valued authorization truth.\n\
         #[derive(Clone, Copy, Debug, Eq, Ord, PartialEq, PartialOrd)]\n\
         pub enum Truth {\n\
         \x20   /// Available facts prove denial.\n\
         \x20   Denied,\n\
         \x20   /// Required facts are unavailable and authorization remains reachable.\n\
         \x20   Indeterminate,\n\
         \x20   /// Available facts prove authorization.\n\
         \x20   Authorized,\n\
         }\n\n\
         /// Shared projection boundary for authority attenuation.\n\
         pub trait AttenuationProjection {\n",
    );
    for dimension in &contract.attenuation_dimensions {
        line!(
            output,
            "    /// Whether {}.",
            dimension_description(&dimension.rust)
        );
        line!(output, "    fn {}(&self) -> bool;", dimension.rust);
    }
    output.push_str(
        "}\n\n\
         /// Concrete projection used by vectors and bounded verification.\n\
         #[allow(\n\
         \x20   clippy::struct_excessive_bools,\n\
         \x20   reason = \"each Boolean is one generated authority dimension\"\n\
         )]\n\
         #[derive(Clone, Copy, Debug, Eq, PartialEq)]\n\
         pub struct AttenuationChecks {\n",
    );
    for dimension in &contract.attenuation_dimensions {
        line!(
            output,
            "    /// Whether {}.",
            dimension_description(&dimension.rust)
        );
        line!(output, "    pub {}: bool,", dimension.rust);
    }
    output.push_str("}\n\nimpl AttenuationProjection for AttenuationChecks {\n");
    for dimension in &contract.attenuation_dimensions {
        line!(output, "    fn {}(&self) -> bool {{", dimension.rust);
        line!(output, "        self.{}", dimension.rust);
        output.push_str("    }\n\n");
    }
    output.pop();
    output.push_str(
        "}\n\n\
         /// Accepts exactly when every declared attenuation dimension accepts.\n\
         #[must_use]\n\
         pub fn attenuation_accepts<P: AttenuationProjection + ?Sized>(projection: &P) -> bool {\n",
    );
    for (index, dimension) in contract.attenuation_dimensions.iter().enumerate() {
        let operator = if index == 0 { "    " } else { "        && " };
        line!(output, "{operator}projection.{}()", dimension.rust);
    }
    output.push_str(
        "}\n\n\
         /// Concrete form of the generated conjunction for mechanical translation.\n\
         #[must_use]\n\
         pub fn attenuation_checks_accept(checks: &AttenuationChecks) -> bool {\n",
    );
    for (index, dimension) in contract.attenuation_dimensions.iter().enumerate() {
        let operator = if index == 0 { "    " } else { "        && " };
        line!(output, "{operator}checks.{}", dimension.rust);
    }
    output.push_str(
        "}\n\n\
         /// Classifies target V1 threshold counts.\n\
         #[must_use]\n\
         pub fn threshold_counts(required: u16, authorized: usize, indeterminate: usize) -> Truth {\n\
         \x20   let required = usize::from(required);\n\
         \x20   if authorized >= required {\n\
         \x20       Truth::Authorized\n\
         \x20   } else if authorized.saturating_add(indeterminate) >= required {\n\
         \x20       Truth::Indeterminate\n\
         \x20   } else {\n\
         \x20       Truth::Denied\n\
         \x20   }\n\
         }\n",
    );
    Ok(output)
}

pub(crate) fn render_lean_algebra(contract: &AlgebraContract) -> Result<String, String> {
    macro_rules! line {
        ($output:expr, $($argument:tt)*) => {
            writeln!($output, $($argument)*)
                .map_err(|_| "could not render generated Lean algebra".to_owned())?
        };
    }

    let mut output = String::new();
    output.push_str(
        "-- @generated by `cargo xtask formal --update`; DO NOT EDIT.\n\n\
         namespace Auths.Generated\n\n",
    );
    line!(
        output,
        "def contractSchema : String := {:?}",
        contract.schema
    );
    line!(
        output,
        "\ndef exhaustiveThresholdBound : Nat := {}",
        contract.exhaustive_threshold_bound
    );
    output.push_str(
        "\ninductive Truth where\n\
         \x20 | denied\n\
         \x20 | indeterminate\n\
         \x20 | authorized\n\
         \x20 deriving BEq, DecidableEq, Repr\n\n\
         structure AttenuationProjection where\n",
    );
    for dimension in &contract.attenuation_dimensions {
        line!(output, "  {} : Bool", dimension.lean);
    }
    output.push_str("  deriving BEq, DecidableEq, Repr\n\n");
    output.push_str("def attenuationAccepts (projection : AttenuationProjection) : Bool :=\n");
    for (index, dimension) in contract.attenuation_dimensions.iter().enumerate() {
        let suffix = if index + 1 == contract.attenuation_dimensions.len() {
            ""
        } else {
            " &&"
        };
        line!(output, "  projection.{}{suffix}", dimension.lean);
    }
    output.push_str(
        "\ndef thresholdCounts (required authorized indeterminate : Nat) : Truth :=\n\
         \x20 if authorized ≥ required then .authorized\n\
         \x20 else if authorized + indeterminate ≥ required then .indeterminate\n\
         \x20 else .denied\n\n\
         end Auths.Generated\n",
    );
    Ok(output)
}

pub(crate) fn synchronize_generated_file(
    path: &Path,
    expected: &str,
    update: bool,
    label: &str,
) -> Result<(), String> {
    if update {
        if let Some(parent) = path.parent() {
            fs::create_dir_all(parent)
                .map_err(|error| format!("could not create {}: {error}", parent.display()))?;
        }
        fs::write(path, expected)
            .map_err(|error| format!("could not write {}: {error}", path.display()))?;
        println!("Updated {label}: {}", path.display());
        return Ok(());
    }
    let actual = fs::read_to_string(path)
        .map_err(|error| format!("could not read {}: {error}", path.display()))?;
    if actual != expected {
        return Err(format!(
            "{label} drifted from formal/algebra-contract-v1.toml; run `cargo xtask formal --update`"
        ));
    }
    Ok(())
}

pub(crate) fn synchronize_algebra_sources(
    contract: &AlgebraContract,
    update: bool,
) -> Result<(), String> {
    synchronize_generated_file(
        &root().join("core/crates/auths-algebra-kernel/src/generated.rs"),
        &render_rust_algebra(contract)?,
        update,
        "generated Rust algebra",
    )?;
    synchronize_generated_file(
        &root().join("formal/Auths/Generated/Algebra.lean"),
        &render_lean_algebra(contract)?,
        update,
        "generated Lean algebra",
    )
}

pub(crate) fn synchronize_lean_vectors(formal_root: &Path, update: bool) -> Result<(), String> {
    for (kind, file) in [
        ("threshold", "threshold-counts.json"),
        ("attenuation", "attenuation-checks.json"),
        ("rich-authority", "rich-authority.json"),
    ] {
        let generated = command_output_in(
            "lake",
            &["exe", "auths-vector-export", kind],
            formal_root,
            None,
        )?;
        serde_json::from_str::<Value>(&generated)
            .map_err(|error| format!("Lean emitted invalid {kind} JSON: {error}"))?;
        synchronize_generated_file(
            &root().join("core/formal-vectors/v1").join(file),
            &generated,
            update,
            &format!("Lean-generated {kind} vectors"),
        )?;
    }
    Ok(())
}

pub(crate) fn formal(skip_kani: bool, update: bool) -> Result<(), String> {
    if !update {
        formal_qualification::validate_source_closure(&root())?;
    }
    let (formal_root, attenuation_dimensions) = prepare_formal(!skip_kani, update)?;
    formal_qualification::validate(&root(), &attenuation_dimensions)?;
    run_formal_semantic_checks(&formal_root, skip_kani, update)
}

/// Generates the actual native adapter ABI for review. This stages raw output
/// only; it cannot mint qualification/reuse/release evidence.
pub(crate) fn formal_extract_native_recipe() -> Result<(), String> {
    let output = formal_qualification::extract_native_recipe_for_review(&root())?;
    println!("Native recipe extraction staged for ABI/model review: {}", output.display());
    println!("Unqualified staging output; no proof or release evidence was produced.");
    Ok(())
}

const FORMAL_PHASE_RESULT_SCHEMA: &str = "auths-proof-formal-phase-result/v1";

#[derive(Clone, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
struct FormalPhaseResult {
    schema: String,
    phase: String,
    head_sha: String,
    run_id: String,
    run_attempt: String,
    planned_closure_sha256: String,
    toolchain_closure_sha256: String,
    evidence_closure_sha256: String,
    toolchain_lock_sha256: String,
    source_closure_sha256: String,
    execution: String,
    reproduction_count: u8,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    reused_from: Option<FormalReuseProducer>,
}

#[derive(Clone, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
struct FormalReuseProducer {
    run_id: String,
    run_attempt: String,
    head_sha: String,
}

/// Early Lean rejection gate. This intentionally emits no qualification
/// evidence and never installs or invokes Aeneas, Charon, or Kani.
pub(crate) fn ci_formal_proof_fast() -> Result<(), String> {
    formal_qualification::validate_source_closure(&root())?;
    let (formal_root, _) = prepare_formal_translation(false, false)?;
    for target in [
        "Auths.Codec.Refinement",
        "Auths.Codec.Encoder",
        "Auths.Product.Refinement.CollectionFence",
        "Auths.Product.Refinement.EntryDeadline",
        "Auths.Refinement.Production",
        "Auths.Refinement.Observation",
        "Auths.Product.Refinement",
        "Auths.Product.Refinement.Gateway",
        "Auths.Product.Refinement.Connections",
        "Auths.Lifecycle.Refinement",
        "Auths.Rich.Mutations",
        "qualification",
    ] {
        command_in("lake", &["build", target], &formal_root, None)?;
    }
    command_in("lake", &["build"], &formal_root, None)?;
    println!("Formal proof fast feedback: PASS (not qualification)");
    Ok(())
}

/// Authoritative translation-only phase: two clean reproductions, byte
/// comparison, and generated/report validation without compiling Lean.
pub(crate) fn ci_formal_translation_reproduce() -> Result<(), String> {
    let update = std::env::var("AUTHS_FORMAL_UPDATE_MODE").as_deref() == Ok("true");
    let attenuation_dimensions = prepare_formal_reproduction(false)?;
    let closure_digest =
        formal_qualification::reproduce_only(&root(), &attenuation_dimensions, update)?;
    write_formal_phase_result("translation", &closure_digest, "executed", 2)?;
    println!("Formal translation phase: PASS (two byte-identical reproductions)");
    Ok(())
}

/// Reuse protected-base or successful same-PR translation evidence only when
/// the current translation, toolchain, and evidence closures all match.
pub(crate) fn ci_formal_translation_reuse() -> Result<(), String> {
    let evidence = std::env::var_os("AUTHS_REUSED_TRANSLATION_EVIDENCE")
        .map(PathBuf::from)
        .ok_or("AUTHS_REUSED_TRANSLATION_EVIDENCE is required")?;
    let closure_digest = formal_qualification::validate_reusable_translation(&root(), &evidence)?;
    let prior = std::env::var_os("AUTHS_REUSED_TRANSLATION_PHASE_RESULT").map(PathBuf::from);
    let producer = if let Some(path) = prior {
        let bytes = fs::read(&path)
            .map_err(|error| format!("could not read {}: {error}", path.display()))?;
        let result: FormalPhaseResult = serde_json::from_slice(&bytes)
            .map_err(|error| format!("invalid reusable phase result: {error}"))?;
        Some(validate_reusable_translation_phase(
            &result,
            &closure_digest,
        )?)
    } else {
        None
    };
    let execution = if producer.is_some() {
        "reused-pr-run"
    } else {
        "reused-protected-base"
    };
    write_formal_phase_result_with_producer(
        "translation",
        &closure_digest,
        execution,
        2,
        producer,
    )?;
    println!("Formal translation phase: REUSED ({execution})");
    Ok(())
}

fn validate_reusable_translation_phase(
    prior: &FormalPhaseResult,
    source_closure_sha256: &str,
) -> Result<FormalReuseProducer, String> {
    let producer = FormalReuseProducer {
        run_id: required_formal_environment("AUTHS_REUSED_RUN_ID")?,
        run_attempt: required_formal_environment("AUTHS_REUSED_RUN_ATTEMPT")?,
        head_sha: required_formal_environment("AUTHS_REUSED_HEAD_SHA")?,
    };
    let current_run_id = required_formal_environment("GITHUB_RUN_ID")?;
    let translation_closure = required_formal_digest("AUTHS_FORMAL_PHASE_CLOSURE_SHA256")?;
    let toolchain_closure = required_formal_digest("AUTHS_FORMAL_TOOLCHAIN_CLOSURE_SHA256")?;
    let evidence_closure = required_formal_digest("AUTHS_FORMAL_EVIDENCE_CLOSURE_SHA256")?;
    let toolchain_lock = formal_toolchain_digest()?;
    let expected = FormalReuseInputs {
        current_run_id: &current_run_id,
        source_closure_sha256,
        translation_closure_sha256: &translation_closure,
        toolchain_closure_sha256: &toolchain_closure,
        evidence_closure_sha256: &evidence_closure,
        toolchain_lock_sha256: &toolchain_lock,
    };
    let matches = reusable_translation_result_matches(prior, &producer, &expected);
    if !matches {
        return Err(
            "prior translation phase does not apply to the current exact inputs".to_owned(),
        );
    }
    Ok(producer)
}

#[derive(Clone, Copy)]
struct FormalReuseInputs<'a> {
    current_run_id: &'a str,
    source_closure_sha256: &'a str,
    translation_closure_sha256: &'a str,
    toolchain_closure_sha256: &'a str,
    evidence_closure_sha256: &'a str,
    toolchain_lock_sha256: &'a str,
}

fn reusable_translation_result_matches(
    prior: &FormalPhaseResult,
    producer: &FormalReuseProducer,
    expected: &FormalReuseInputs<'_>,
) -> bool {
    producer.run_id != expected.current_run_id
        && producer.run_id.parse::<u64>().is_ok()
        && producer.run_attempt.parse::<u32>().is_ok()
        && producer.head_sha.len() == 40
        && producer
            .head_sha
            .bytes()
            .all(|byte| byte.is_ascii_hexdigit() && !byte.is_ascii_uppercase())
        && prior.schema == FORMAL_PHASE_RESULT_SCHEMA
        && prior.phase == "translation"
        && prior.run_id == producer.run_id
        && prior.run_attempt == producer.run_attempt
        && prior.head_sha == producer.head_sha
        && prior.planned_closure_sha256 == expected.translation_closure_sha256
        && prior.toolchain_closure_sha256 == expected.toolchain_closure_sha256
        && prior.evidence_closure_sha256 == expected.evidence_closure_sha256
        && prior.toolchain_lock_sha256 == expected.toolchain_lock_sha256
        && prior.source_closure_sha256 == expected.source_closure_sha256
        && matches!(
            prior.execution.as_str(),
            "executed" | "reused-protected-base" | "reused-pr-run"
        )
        && prior.reproduction_count == 2
}

/// Clean authoritative Lean build plus the existing assurance, qualification,
/// semantic-vector, and Rust-refinement gates. Kani runs in its own job.
pub(crate) fn ci_formal_lean_authoritative() -> Result<(), String> {
    let update = std::env::var("AUTHS_FORMAL_UPDATE_MODE").as_deref() == Ok("true");
    let closure_digest = formal_qualification::validate_source_closure(&root())?;
    let (formal_root, attenuation_dimensions) = prepare_formal_translation(false, false)?;
    clear_repository_lean_outputs(&formal_root)?;
    build_and_audit_formal(&formal_root, update)?;
    // Replay the public theorem closure into an empty kernel environment.
    // This catches environment manipulation; it is separate from checking
    // theorem meaning and the transitive axiom allowlist above.
    command_in(
        "lake",
        &["env", "leanchecker", "--fresh", "Auths.Theorems"],
        &formal_root,
        None,
    )?;
    formal_qualification::validate(&root(), &attenuation_dimensions)?;
    run_formal_semantic_checks(&formal_root, true, false)?;
    write_formal_phase_result("lean", &closure_digest, "executed-clean", 0)?;
    Ok(())
}

/// Complete bounded-model phase, isolated so installing Kani never delays a
/// Lean diagnostic or translation setup.
pub(crate) fn ci_formal_kani() -> Result<(), String> {
    validate_kani_toolchain()?;
    let closure_digest = formal_qualification::validate_source_closure(&root())?;
    kani_harness_inventory()?;
    run_kani_harnesses()?;
    write_formal_phase_result("kani", &closure_digest, "executed", 0)
}

/// Exact-revision formal result aggregator. Phase artifacts are downloaded
/// into the result directory by hosted CI; no implementation job can declare
/// the overall formal decision independently.
pub(crate) fn ci_formal_evidence() -> Result<(), String> {
    let expected_head = current_git_head()?;
    let expected_run_id = required_formal_environment("GITHUB_RUN_ID")?;
    let current_run_attempt = required_formal_environment("GITHUB_RUN_ATTEMPT")?;
    let expected_toolchain = required_formal_digest("AUTHS_FORMAL_TOOLCHAIN_CLOSURE_SHA256")?;
    let expected_evidence = required_formal_digest("AUTHS_FORMAL_EVIDENCE_CLOSURE_SHA256")?;
    let expected_toolchain_lock = formal_toolchain_digest()?;
    let expected_closure = formal_qualification::validate_source_closure(&root())?;
    for (phase, expected_execution, digest_variable) in [
        (
            "translation",
            None,
            "AUTHS_FORMAL_TRANSLATION_CLOSURE_SHA256",
        ),
        (
            "lean",
            Some("executed-clean"),
            "AUTHS_FORMAL_PROOF_CLOSURE_SHA256",
        ),
        ("kani", Some("executed"), "AUTHS_FORMAL_KANI_CLOSURE_SHA256"),
    ] {
        let result = read_formal_phase_result(phase)?;
        let expected_phase_digest = required_formal_digest(digest_variable)?;
        let selected_attempt = required_formal_environment(&format!(
            "AUTHS_FORMAL_{}_SOURCE_ATTEMPT",
            phase.to_ascii_uppercase()
        ))?;
        if result.schema != FORMAL_PHASE_RESULT_SCHEMA
            || result.phase != phase
            || result.head_sha != expected_head
            || result.run_id != expected_run_id
            || !phase_result_attempt_matches(
                &result.run_attempt,
                &selected_attempt,
                &current_run_attempt,
            )
            || result.planned_closure_sha256 != expected_phase_digest
            || result.toolchain_closure_sha256 != expected_toolchain
            || result.evidence_closure_sha256 != expected_evidence
            || result.toolchain_lock_sha256 != expected_toolchain_lock
            || result.source_closure_sha256 != expected_closure
            || expected_execution.is_some_and(|expected| result.execution != expected)
            || (phase == "translation"
                && (result.reproduction_count != 2
                    || !matches!(
                        result.execution.as_str(),
                        "executed" | "reused-protected-base" | "reused-pr-run"
                    )
                    || (result.execution == "reused-pr-run" && result.reused_from.is_none())))
        {
            return Err(format!(
                "formal {phase} evidence is stale, malformed, or does not apply to head {expected_head}"
            ));
        }
    }
    write_formal_phase_result("evidence", &expected_closure, "aggregated", 0)?;
    println!("Formal evidence: PASS (translation + clean Lean + Kani)");
    Ok(())
}

fn phase_result_attempt_matches(
    result_attempt: &str,
    selected_attempt: &str,
    current_attempt: &str,
) -> bool {
    let Ok(selected) = selected_attempt.parse::<u32>() else {
        return false;
    };
    let Ok(current) = current_attempt.parse::<u32>() else {
        return false;
    };
    selected > 0
        && selected <= current
        && selected_attempt == selected.to_string()
        && current_attempt == current.to_string()
        && result_attempt == selected_attempt
}

fn clear_repository_lean_outputs(formal_root: &Path) -> Result<(), String> {
    for relative in [
        ".lake/build/lib/lean/Auths",
        ".lake/build/lib/lean/qualification",
        ".lake/build/ir/Auths",
        ".lake/build/ir/qualification",
    ] {
        let path = formal_root.join(relative);
        if path.exists() {
            fs::remove_dir_all(&path)
                .map_err(|error| format!("could not remove {}: {error}", path.display()))?;
        }
    }
    Ok(())
}

fn current_git_head() -> Result<String, String> {
    Ok(
        command_output_in("git", &["rev-parse", "HEAD"], &root(), None)?
            .trim()
            .to_owned(),
    )
}

fn formal_toolchain_digest() -> Result<String, String> {
    let path = root().join("formal/translation-toolchain.lock");
    let bytes =
        fs::read(&path).map_err(|error| format!("could not read {}: {error}", path.display()))?;
    Ok(hex::encode(Sha256::digest(bytes)))
}

fn formal_phase_result_path(phase: &str) -> PathBuf {
    root()
        .join("target/formal/phase-results")
        .join(format!("{phase}.json"))
}

fn write_formal_phase_result(
    phase: &str,
    source_closure_sha256: &str,
    execution: &str,
    reproduction_count: u8,
) -> Result<(), String> {
    write_formal_phase_result_with_producer(
        phase,
        source_closure_sha256,
        execution,
        reproduction_count,
        None,
    )
}

fn write_formal_phase_result_with_producer(
    phase: &str,
    source_closure_sha256: &str,
    execution: &str,
    reproduction_count: u8,
    reused_from: Option<FormalReuseProducer>,
) -> Result<(), String> {
    let result = FormalPhaseResult {
        schema: FORMAL_PHASE_RESULT_SCHEMA.to_owned(),
        phase: phase.to_owned(),
        head_sha: current_git_head()?,
        run_id: required_formal_environment("GITHUB_RUN_ID")?,
        run_attempt: required_formal_environment("GITHUB_RUN_ATTEMPT")?,
        planned_closure_sha256: required_formal_digest("AUTHS_FORMAL_PHASE_CLOSURE_SHA256")?,
        toolchain_closure_sha256: required_formal_digest("AUTHS_FORMAL_TOOLCHAIN_CLOSURE_SHA256")?,
        evidence_closure_sha256: required_formal_digest("AUTHS_FORMAL_EVIDENCE_CLOSURE_SHA256")?,
        toolchain_lock_sha256: formal_toolchain_digest()?,
        source_closure_sha256: source_closure_sha256.to_owned(),
        execution: execution.to_owned(),
        reproduction_count,
        reused_from,
    };
    let path = formal_phase_result_path(phase);
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent)
            .map_err(|error| format!("could not create {}: {error}", parent.display()))?;
    }
    let mut bytes = serde_json::to_vec_pretty(&result)
        .map_err(|error| format!("could not encode formal {phase} result: {error}"))?;
    bytes.push(b'\n');
    fs::write(&path, bytes).map_err(|error| format!("could not write {}: {error}", path.display()))
}

fn required_formal_digest(variable: &str) -> Result<String, String> {
    let value = required_formal_environment(variable)?;
    if value.len() != 64
        || !value
            .bytes()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
    {
        return Err(format!("{variable} must be a lowercase SHA-256 digest"));
    }
    Ok(value)
}

fn required_formal_environment(variable: &str) -> Result<String, String> {
    std::env::var(variable)
        .ok()
        .filter(|value| !value.trim().is_empty())
        .ok_or_else(|| format!("{variable} is required"))
}

fn read_formal_phase_result(phase: &str) -> Result<FormalPhaseResult, String> {
    let path = formal_phase_result_path(phase);
    serde_json::from_slice(
        &fs::read(&path).map_err(|error| format!("could not read {}: {error}", path.display()))?,
    )
    .map_err(|error| format!("invalid formal phase result {}: {error}", path.display()))
}

fn validate_kani_toolchain() -> Result<(), String> {
    let path = root().join("formal/translation-toolchain.lock");
    let lock: toml::Value = toml::from_str(
        &fs::read_to_string(&path)
            .map_err(|error| format!("could not read {}: {error}", path.display()))?,
    )
    .map_err(|error| format!("invalid formal toolchain lock {}: {error}", path.display()))?;
    let required = |table: &str, field: &str| -> Result<&str, String> {
        lock.get(table)
            .and_then(toml::Value::as_table)
            .and_then(|value| value.get(field))
            .and_then(toml::Value::as_str)
            .ok_or_else(|| format!("formal toolchain lock omits {table}.{field}"))
    };
    let rust = command_output_in("rustc", &["--version"], &root(), None)?;
    let rust_version = required("rust", "shipping")?;
    if !rust.contains(&format!("rustc {rust_version} ")) {
        return Err(format!(
            "formal shipping Rust drift: expected {rust_version}, found {rust}"
        ));
    }
    let kani = command_output_in("kani", &["--version"], &root(), None)?;
    let kani_version = required("kani", "version")?;
    if !kani.contains(kani_version) {
        return Err(format!(
            "formal Kani drift: expected {kani_version}, found {kani}"
        ));
    }
    Ok(())
}

/// One workspace package whose `#[kani::proof]` harnesses the formal gate runs.
struct KaniHarnessPackage {
    /// Cargo package name passed to `cargo kani -p`.
    package: &'static str,
    /// Workspace-relative source root that must contain every harness the
    /// package owns.
    source_root: &'static str,
}

/// Complete inventory of packages carrying Kani harnesses.
///
/// `kani_harness_inventory` fails the gate when any `#[kani::proof]` appears
/// outside these roots. Before this list existed the gate ran only the two core
/// packages, so 31 product harnesses were never executed by anything — which is
/// the structural reason single-point harnesses could wear universally
/// quantified names undetected. Adding a harness in a new package must extend
/// this list, not silently skip the gate.
const KANI_HARNESS_PACKAGES: &[KaniHarnessPackage] = &[
    KaniHarnessPackage {
        package: "auths-algebra-kernel",
        source_root: "core/crates/auths-algebra-kernel",
    },
    KaniHarnessPackage {
        package: "auths-model",
        source_root: "core/crates/auths-model",
    },
    KaniHarnessPackage {
        package: "auths-lifecycle",
        source_root: "product/runtime/auths-lifecycle",
    },
    KaniHarnessPackage {
        package: "auths-bounded-policy",
        source_root: "product/policy/auths-bounded-policy",
    },
    KaniHarnessPackage {
        package: "auths-gateway-kernel",
        source_root: "product/runtime/auths-gateway-kernel",
    },
    KaniHarnessPackage {
        package: "auths-stripe",
        source_root: "product/integrations/auths-stripe",
    },
];

/// Runs the complete harness set for every package in `KANI_HARNESS_PACKAGES`.
///
/// Nothing is filtered. Kani 0.67 offers only an inclusion filter
/// (`--harness`), so excluding one slow harness would mean hand-listing every
/// other harness name here — a list that goes stale exactly the way the phantom
/// `kani_harnesses` citations did. The complete set is run instead.
///
/// MEASURED COST of the 31 product harnesses this list newly gates: ~281s of
/// solving, of which ~235s is the single harness
/// `connect::transfer::evaluator::proofs::basis_points_floor_never_exceeds_denominator`
/// (symbolic 64-bit division by 10_000; kissat was tried and was slower at
/// ~279s). Every other harness is under 0.3s. If this gate needs to get faster,
/// make that division cheaper to reason about — do not shrink its input domain.
fn run_kani_harnesses() -> Result<(), String> {
    for package in KANI_HARNESS_PACKAGES.iter().map(|entry| entry.package) {
        command_in(
            "cargo",
            // `-j` requires terse output; both are needed to keep the wall
            // clock down while still running the complete set.
            &["kani", "-p", package, "-j", "--output-format=terse"],
            &root(),
            None,
        )?;
    }
    println!("Kani bounded harnesses:      PASS (complete set)");
    Ok(())
}

/// Fails when a `#[kani::proof]` exists that no gated package would run, or
/// that a change would not schedule.
///
/// This runs even under `--skip-kani`: skipping execution is a local
/// convenience, but an unrunnable harness is a permanent evidence gap and must
/// be reported either way. The planner schedules Kani from its Kani closure,
/// so every gated package and harness file must lie inside that closure.
fn kani_harness_inventory() -> Result<(), String> {
    let root = root();
    let unplanned_packages = KANI_HARNESS_PACKAGES
        .iter()
        .filter(|entry| {
            !auths_ci_plan::kani_closure_contains(&format!("{}/Cargo.toml", entry.source_root))
        })
        .map(|entry| entry.package)
        .collect::<Vec<_>>();
    if !unplanned_packages.is_empty() {
        return Err(format!(
            "Kani harness packages lie outside the planner's Kani closure, so a change to \
             them would not schedule the Kani job; extend FormalClosureKind::Kani in \
             xtask/ci-plan/src/lib.rs: {}",
            unplanned_packages.join(", ")
        ));
    }
    let mut orphans = Vec::new();
    let mut unplanned = Vec::new();
    let mut total = 0_usize;
    let mut sources = Vec::new();
    collect_rust_sources(&root, &root, &mut sources)?;
    sources.sort();
    for relative in sources {
        let text = fs::read_to_string(root.join(&relative))
            .map_err(|error| format!("could not read {}: {error}", relative.display()))?;
        let count = text
            .lines()
            .filter(|line| line.trim_start().starts_with("#[kani::proof]"))
            .count();
        if count == 0 {
            continue;
        }
        total += count;
        let display = relative.to_string_lossy().replace('\\', "/");
        if !KANI_HARNESS_PACKAGES
            .iter()
            .any(|entry| display.starts_with(&format!("{}/", entry.source_root)))
        {
            orphans.push(format!("{display} ({count} harnesses)"));
        }
        if !auths_ci_plan::kani_closure_contains(&display) {
            unplanned.push(display);
        }
    }
    if !orphans.is_empty() {
        return Err(format!(
            "Kani harnesses exist that no gated package runs; add the owning package to \
             KANI_HARNESS_PACKAGES in xtask/src/formal.rs: {}",
            orphans.join(", ")
        ));
    }
    if !unplanned.is_empty() {
        return Err(format!(
            "Kani harness files lie outside the planner's Kani closure; extend \
             FormalClosureKind::Kani in xtask/ci-plan/src/lib.rs: {}",
            unplanned.join(", ")
        ));
    }
    let packages = KANI_HARNESS_PACKAGES
        .iter()
        .map(|entry| (entry.package, root.join(entry.source_root)))
        .collect::<Vec<_>>();
    let calling = crate::kani_harness::lint_harness_calls(&packages)?;
    if calling != total {
        return Err(format!(
            "the harness call lint parsed {calling} harnesses but the inventory counts {total}; \
             a harness the lint cannot parse would go unchecked"
        ));
    }
    println!(
        "Kani harness inventory:      PASS ({total} harnesses, all gated and calling their crate)"
    );
    Ok(())
}

/// Collects workspace-relative paths of every `.rs` file outside build output.
fn collect_rust_sources(
    root: &Path,
    directory: &Path,
    found: &mut Vec<PathBuf>,
) -> Result<(), String> {
    let entries = fs::read_dir(directory)
        .map_err(|error| format!("could not read {}: {error}", directory.display()))?;
    for entry in entries {
        let entry = entry.map_err(|error| format!("could not read a directory entry: {error}"))?;
        let path = entry.path();
        let name = entry.file_name();
        let name = name.to_string_lossy();
        if name.starts_with('.') || name == "target" || name == "node_modules" {
            continue;
        }
        let kind = entry
            .file_type()
            .map_err(|error| format!("could not stat {}: {error}", path.display()))?;
        if kind.is_dir() {
            collect_rust_sources(root, &path, found)?;
        } else if kind.is_file() && path.extension().is_some_and(|value| value == "rs") {
            let relative = path
                .strip_prefix(root)
                .map_err(|error| format!("path escaped the workspace root: {error}"))?;
            found.push(relative.to_path_buf());
        }
    }
    Ok(())
}

/// Prepares everything that does NOT read committed generated Lean.
///
/// Synchronizes the algebra contract sources, validates the pinned toolchain,
/// and returns the attenuation dimensions. It deliberately runs neither `lake
/// build` nor the assurance audit.
///
/// `formal qualify aeneas` regenerates the very Lean a build would compile, so
/// building first makes regeneration impossible the moment a translation starts
/// referencing a symbol its upstream crate has not exported yet: the build
/// fails on the generated file, qualification aborts before `reproduce()`, and
/// the upstream crate can never produce the symbol. Translation must come
/// first; the complete build and audit still gate success, from
/// [`build_and_audit_formal`] after synchronization.
const MUTATION_CASE_IDS: [&str; 23] = [
    "validity-start-direction",
    "validity-end-direction",
    "permission-subset-direction",
    "audience-subset-direction",
    "permission-membership-decision",
    "audience-membership-decision",
    "body-digest-membership-decision",
    "body-digest-subset-direction",
    "action-exact-equality",
    "action-constructor-fallback",
    "action-singleton-exact-rejection",
    "budget-value-direction",
    "budget-algebra-equality",
    "optional-budget-bounded-parent",
    "optional-budget-no-request",
    "status-age-direction",
    "status-method-equality",
    "profile-version-equality",
    "assurance-equality",
    "critical-extension-law",
    "delegation-depth-strictness",
    "principal-linkage-equality",
    "grant-linkage-equality",
];

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct MutationMatrix {
    schema: String,
    cases: Vec<MutationCase>,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct MutationCase {
    id: String,
    operator: String,
    witness: String,
    lean_declaration: String,
}

fn expected_mutation_declaration(identifier: &str) -> String {
    format!("Auths.Rich.Mutations.{}", identifier.replace('-', "_"))
}

/// Requires the mutation matrix to have exactly the reviewed schema and all 23
/// compiled witnesses. Malformed JSON, omitted declarations, duplicate or
/// unknown identifiers, and redirection to an unrelated theorem all fail
/// closed: this artifact is executable assurance evidence, not prose.
fn validate_mutation_witnesses(
    artifact: &Path,
    compiled: &BTreeMap<String, LeanAssuranceDeclaration>,
) -> Result<(), String> {
    if artifact.file_name().and_then(|value| value.to_str()) != Some("refinement-mutations-v1.json")
    {
        return Ok(());
    }
    let source = fs::read_to_string(artifact).map_err(|error| {
        format!(
            "could not read mutation matrix {}: {error}",
            artifact.display()
        )
    })?;
    validate_mutation_matrix_source(&source, compiled)
}

fn validate_mutation_matrix_source(
    source: &str,
    compiled: &BTreeMap<String, LeanAssuranceDeclaration>,
) -> Result<(), String> {
    let matrix: MutationMatrix = serde_json::from_str(source)
        .map_err(|error| format!("invalid mutation matrix: {error}"))?;
    if matrix.schema != "auths-proof-semantic-mutations/v1" {
        return Err(format!(
            "unsupported mutation matrix schema {}",
            matrix.schema
        ));
    }
    if matrix.cases.len() != MUTATION_CASE_IDS.len() {
        return Err(format!(
            "mutation matrix must contain exactly {} cases, found {}",
            MUTATION_CASE_IDS.len(),
            matrix.cases.len()
        ));
    }
    let mut seen = BTreeSet::new();
    for (index, case) in matrix.cases.iter().enumerate() {
        let expected_id = MUTATION_CASE_IDS[index];
        if case.id != expected_id {
            return Err(format!(
                "mutation case {index} must be {expected_id}, found {}",
                case.id
            ));
        }
        if !seen.insert(case.id.as_str()) {
            return Err(format!("mutation matrix repeats case {}", case.id));
        }
        if case.operator.trim().is_empty() || case.witness.trim().is_empty() {
            return Err(format!("mutation case {} is incomplete", case.id));
        }
        let expected = expected_mutation_declaration(&case.id);
        if case.lean_declaration != expected {
            return Err(format!(
                "mutation case {} must name deterministic witness {expected}, found {}",
                case.id, case.lean_declaration
            ));
        }
        let declaration = compiled.get(&case.lean_declaration).ok_or_else(|| {
            format!(
                "mutation case {} names witness {}, which the assurance audit did not compile",
                case.id, case.lean_declaration
            )
        })?;
        if declaration.kind != "theorem" {
            return Err(format!(
                "mutation case {} witness {} compiled as {}, not theorem",
                case.id, case.lean_declaration, declaration.kind
            ));
        }
    }
    Ok(())
}

pub(crate) fn prepare_formal_translation(
    require_kani: bool,
    update: bool,
) -> Result<(PathBuf, Vec<String>), String> {
    let formal_root = root().join("formal");
    let contract = load_algebra_contract()?;
    synchronize_algebra_sources(&contract, update)?;
    validate_formal_toolchain(&formal_root, require_kani)?;
    let attenuation_dimensions = contract
        .attenuation_dimensions
        .iter()
        .map(|dimension| dimension.rust.clone())
        .collect();
    Ok((formal_root, attenuation_dimensions))
}

/// Prepare only inputs needed by Aeneas/Charon reproduction. This deliberately
/// does not require Lean or Kani; those tools are owned by independent jobs.
fn prepare_formal_reproduction(update: bool) -> Result<Vec<String>, String> {
    let formal_root = root().join("formal");
    let contract = load_algebra_contract()?;
    synchronize_algebra_sources(&contract, update)?;
    validate_shipping_rust_toolchain(&formal_root)?;
    Ok(contract
        .attenuation_dimensions
        .iter()
        .map(|dimension| dimension.rust.clone())
        .collect())
}

fn validate_shipping_rust_toolchain(formal_root: &Path) -> Result<(), String> {
    let path = formal_root.join("translation-toolchain.lock");
    let lock: toml::Value = toml::from_str(
        &fs::read_to_string(&path)
            .map_err(|error| format!("could not read {}: {error}", path.display()))?,
    )
    .map_err(|error| format!("invalid formal toolchain lock {}: {error}", path.display()))?;
    if lock.get("schema").and_then(toml::Value::as_str) != Some("auths-proof-formal-toolchain/v1") {
        return Err("unsupported formal toolchain lock schema".to_owned());
    }
    let shipping_rust = lock
        .get("rust")
        .and_then(toml::Value::as_table)
        .and_then(|value| value.get("shipping"))
        .and_then(toml::Value::as_str)
        .ok_or("formal toolchain lock omits rust.shipping")?;
    let rust = command_output_in("rustc", &["--version"], &root(), None)?;
    if !rust.contains(&format!("rustc {shipping_rust} ")) {
        return Err(format!(
            "formal shipping Rust drift: lock requires {shipping_rust}, command reported {}",
            rust.trim()
        ));
    }
    Ok(())
}

/// Compiles the Lean development and runs the compiled assurance audit.
///
/// Separated from [`prepare_formal_translation`] so qualification can run it
/// AFTER regenerated outputs and reviewed bridges are in place. This is the
/// gate: qualification does not succeed without it.
pub(crate) fn build_and_audit_formal(formal_root: &Path, update: bool) -> Result<(), String> {
    command_in("lake", &["build"], formal_root, None)?;
    formal_assurance_audit(formal_root, update)
}

/// Build-first preparation used by ordinary `cargo xtask formal`.
///
/// Unchanged behaviour: everything downstream reads committed generated Lean,
/// so the build belongs up front. Only `formal qualify aeneas` inverts this.
pub(crate) fn prepare_formal(
    require_kani: bool,
    update: bool,
) -> Result<(PathBuf, Vec<String>), String> {
    let (formal_root, attenuation_dimensions) = prepare_formal_translation(require_kani, update)?;
    build_and_audit_formal(&formal_root, update)?;
    Ok((formal_root, attenuation_dimensions))
}

pub(crate) fn run_formal_semantic_checks(
    formal_root: &Path,
    skip_kani: bool,
    update: bool,
) -> Result<(), String> {
    synchronize_lean_vectors(formal_root, update)?;

    cargo(&["test", "-p", "auths-formal-refinement"])?;
    kani_harness_inventory()?;
    if skip_kani {
        println!("Kani bounded harnesses:      SKIPPED (--skip-kani)");
    } else {
        run_kani_harnesses()?;
    }
    println!("Lean theorems:              PASS");
    println!("Generated semantic vectors: byte-stable");
    println!("Rust refinement vectors:    PASS");
    Ok(())
}

pub(crate) fn validate_formal_toolchain(
    formal_root: &Path,
    require_kani: bool,
) -> Result<(), String> {
    let path = formal_root.join("translation-toolchain.lock");
    let source = fs::read_to_string(&path)
        .map_err(|error| format!("could not read {}: {error}", path.display()))?;
    let lock: toml::Value = toml::from_str(&source)
        .map_err(|error| format!("invalid formal toolchain lock {}: {error}", path.display()))?;
    if lock.get("schema").and_then(toml::Value::as_str) != Some("auths-proof-formal-toolchain/v1") {
        return Err("unsupported formal toolchain lock schema".to_owned());
    }
    let required = |table: &str, field: &str| -> Result<&str, String> {
        lock.get(table)
            .and_then(toml::Value::as_table)
            .and_then(|value| value.get(field))
            .and_then(toml::Value::as_str)
            .ok_or_else(|| format!("formal toolchain lock omits {table}.{field}"))
    };

    let rust = command_output_in("rustc", &["--version"], &root(), None)?;
    let shipping_rust = required("rust", "shipping")?;
    if !rust.contains(&format!("rustc {shipping_rust} ")) {
        return Err(format!(
            "formal shipping Rust drift: lock requires {shipping_rust}, command reported {}",
            rust.trim()
        ));
    }
    let lean = command_output_in("lean", &["--version"], formal_root, None)?;
    let lean_commit = required("lean", "commit")?;
    if !lean.contains(lean_commit) {
        return Err(format!(
            "formal Lean drift: lock requires commit {lean_commit}, command reported {}",
            lean.trim()
        ));
    }
    let lean_toolchain_path = formal_root.join("lean-toolchain");
    let lean_toolchain = fs::read_to_string(&lean_toolchain_path)
        .map_err(|error| format!("could not read {}: {error}", lean_toolchain_path.display()))?;
    if lean_toolchain.trim() != required("lean", "toolchain")? {
        return Err("formal Lean toolchain file and lock differ".to_owned());
    }
    if require_kani {
        let kani = command_output_in("kani", &["--version"], &root(), None)?;
        let kani_version = required("kani", "version")?;
        if kani.trim() != format!("kani {kani_version}") {
            return Err(format!(
                "formal Kani drift: lock requires {kani_version}, command reported {}",
                kani.trim()
            ));
        }
    }
    println!("Formal toolchain lock:       PASS");
    Ok(())
}

#[derive(Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct FormalAssuranceManifest {
    schema: String,
    lean_toolchain: String,
    toolchain_lock_sha256: String,
    /// Human-reviewed batch identifier for the exact compiled declaration set.
    statement_review: String,
    /// Digest of names, modules, kinds, statements, and transitive axioms.
    /// Qualification never refreshes this field automatically.
    statement_inventory_sha256: String,
    allowed_axioms: Vec<String>,
    /// One independently resolved closure; every claim binds its digest.
    semantic_source_closure: FormalSemanticSourceClosure,
    claims: Vec<FormalAssuranceClaim>,
}

#[derive(Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
struct FormalSemanticSourceClosure {
    sha256: String,
    paths: Vec<String>,
}

#[derive(Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct FormalAssuranceClaim {
    claim_id: String,
    claim_text: String,
    claim_status: String,
    lean_declaration: String,
    lean_statement_sha256: String,
    formal_review: String,
    rust_symbols: Vec<String>,
    /// Reference to the manifest's shared closure, checked for every claim.
    semantic_source_closure_sha256: String,
    evidence: Vec<FormalEvidence>,
    scope: String,
    residual_assumptions: Vec<String>,
    toolchain_lock_sha256: String,
    axioms: Vec<String>,
}

#[derive(Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct FormalEvidence {
    kind: FormalEvidenceKind,
    artifact: String,
    /// SHA-256 of the artifact's bytes.
    ///
    /// Evidence used to be EXISTENCE-CHECKED only: the audit confirmed a file
    /// was present at the path and read nothing. An artifact could be emptied,
    /// rewritten, or replaced wholesale and every claim citing it still passed.
    ///
    /// Mandatory. Update mode computes it; check mode verifies it. An evidence
    /// entry is never permitted to exist in an unhashed intermediate state.
    sha256: String,
}

#[derive(Clone, Copy, Deserialize, Eq, PartialEq, Serialize)]
#[serde(rename_all = "kebab-case")]
enum FormalEvidenceKind {
    LeanProof,
    LeanRefinement,
    MechanicalTranslation,
    TranslatedRust,
    SourceClosure,
    LeanGeneratedVectors,
    MutationMatrix,
    TestCorpus,
}

impl FormalEvidenceKind {
    fn validates_path(self, path: &str) -> bool {
        match self {
            Self::LeanProof | Self::LeanRefinement => path.ends_with(".lean"),
            Self::MechanicalTranslation | Self::TranslatedRust => {
                path.starts_with("formal/qualification/aeneas/generated/")
                    && path.ends_with(".lean")
            }
            Self::SourceClosure => path == "formal/qualification/aeneas/source-closure.json",
            Self::LeanGeneratedVectors => {
                path.starts_with("core/formal-vectors/v1/") && path.ends_with(".json")
            }
            Self::MutationMatrix => path == "formal/refinement-mutations-v1.json",
            Self::TestCorpus => !path.trim().is_empty(),
        }
    }
}

fn validated_evidence_path(relative: &str) -> Result<PathBuf, String> {
    let path = Path::new(relative);
    if path.is_absolute()
        || path
            .components()
            .any(|component| !matches!(component, std::path::Component::Normal(_)))
    {
        return Err(format!(
            "evidence path must be a normalized workspace-relative path: {relative}"
        ));
    }
    let unresolved = root().join(path);
    let metadata = fs::symlink_metadata(&unresolved)
        .map_err(|error| format!("could not stat evidence {}: {error}", unresolved.display()))?;
    if !metadata.file_type().is_file() || metadata.file_type().is_symlink() {
        return Err(format!(
            "evidence path is not a regular non-symlink file: {relative}"
        ));
    }
    let workspace = fs::canonicalize(root())
        .map_err(|error| format!("could not resolve workspace root: {error}"))?;
    let resolved = fs::canonicalize(&unresolved).map_err(|error| {
        format!(
            "could not resolve evidence {}: {error}",
            unresolved.display()
        )
    })?;
    if !resolved.starts_with(&workspace) {
        return Err(format!("evidence path escapes workspace: {relative}"));
    }
    Ok(resolved)
}

fn validate_sha256(value: &str) -> Result<(), String> {
    if value.len() == 64
        && value
            .bytes()
            .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
    {
        Ok(())
    } else {
        Err(format!("invalid lowercase SHA-256 {value}"))
    }
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct LeanAssuranceAudit {
    schema: String,
    declarations: Vec<LeanAssuranceDeclaration>,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct LeanAssuranceDeclaration {
    name: String,
    module: String,
    kind: String,
    statement: String,
    axioms: Vec<String>,
    statement_constants: Vec<String>,
}

fn lean_statement_inventory_sha256(audit: &LeanAssuranceAudit) -> String {
    let mut declarations = audit.declarations.iter().collect::<Vec<_>>();
    declarations.sort_by(|left, right| left.name.cmp(&right.name));
    let mut digest = Sha256::new();
    for declaration in declarations {
        let mut axioms = declaration.axioms.clone();
        axioms.sort();
        for value in [
            declaration.name.as_str(),
            declaration.module.as_str(),
            declaration.kind.as_str(),
            declaration.statement.as_str(),
        ] {
            digest.update(value.as_bytes());
            digest.update([0]);
        }
        for axiom in axioms {
            digest.update(axiom.as_bytes());
            digest.update([0]);
        }
        let mut constants = declaration.statement_constants.clone();
        constants.sort();
        digest.update([0xfe]);
        for constant in constants {
            digest.update(constant.as_bytes());
            digest.update([0]);
        }
        digest.update([0xff]);
    }
    hex::encode(digest.finalize())
}

/// Resolve references only against the independently discovered paths and
/// freshly hashed source bytes, never against a producer-supplied closure.
fn validate_manifest_source_closure(
    manifest: &FormalAssuranceManifest,
    expected_paths: &[String],
    expected_digest: &str,
) -> Result<(), String> {
    let closure = &manifest.semantic_source_closure;
    if closure.paths.is_empty() {
        return Err(
            "formal assurance manifest must declare a shared semantic source closure".to_owned(),
        );
    }
    if closure.paths != expected_paths {
        return Err(
            "formal assurance manifest semantic source closure is not the Lean-resolved transitive assurance closure"
                .to_owned(),
        );
    }
    validate_sha256(&closure.sha256)
        .map_err(|error| format!("invalid shared semantic source closure digest: {error}"))?;
    if closure.sha256 != expected_digest {
        return Err(format!(
            "formal assurance manifest semantic source closure drifted: expected {}, found {expected_digest}",
            closure.sha256
        ));
    }
    for claim in &manifest.claims {
        if claim.semantic_source_closure_sha256 != closure.sha256 {
            return Err(format!(
                "formal claim {} semantic source closure reference drifted: expected {}, found {}",
                claim.lean_declaration, closure.sha256, claim.semantic_source_closure_sha256
            ));
        }
    }
    Ok(())
}

pub(crate) fn formal_assurance_audit(formal_root: &Path, update: bool) -> Result<(), String> {
    let manifest_path = formal_root.join("assurance-manifest-v1.toml");
    let mut manifest: FormalAssuranceManifest = toml::from_str(
        &fs::read_to_string(&manifest_path)
            .map_err(|error| format!("could not read {}: {error}", manifest_path.display()))?,
    )
    .map_err(|error| {
        format!(
            "invalid assurance manifest {}: {error}",
            manifest_path.display()
        )
    })?;
    if manifest.schema != "auths-proof-formal-assurance/v1" {
        return Err(format!(
            "unsupported formal assurance schema {}",
            manifest.schema
        ));
    }

    let lean_toolchain_path = formal_root.join("lean-toolchain");
    let lean_toolchain = fs::read_to_string(&lean_toolchain_path)
        .map_err(|error| format!("could not read {}: {error}", lean_toolchain_path.display()))?;
    if lean_toolchain.trim() != manifest.lean_toolchain {
        return Err("formal assurance manifest Lean toolchain drifted".to_owned());
    }

    let toolchain_lock_path = formal_root.join("translation-toolchain.lock");
    let toolchain_lock_digest = sha256_file(&toolchain_lock_path)?;
    if manifest.toolchain_lock_sha256 != toolchain_lock_digest {
        return Err(format!(
            "formal toolchain lock drifted: expected {}, found {toolchain_lock_digest}",
            manifest.toolchain_lock_sha256
        ));
    }

    let audit_output = command_output_in(
        "lake",
        &["env", "lean", "Auths/AssuranceAudit.lean"],
        formal_root,
        None,
    )?;
    let audit: LeanAssuranceAudit = serde_json::from_str(audit_output.trim())
        .map_err(|error| format!("compiled Lean assurance audit emitted invalid JSON: {error}"))?;
    if audit.schema != "auths-proof-lean-assurance-audit/v1" {
        return Err(format!(
            "unsupported compiled Lean assurance audit schema {}",
            audit.schema
        ));
    }
    let statement_inventory_sha256 = lean_statement_inventory_sha256(&audit);
    if manifest.statement_review.trim().is_empty() {
        return Err("formal assurance statement review batch is empty".to_owned());
    }
    if manifest.statement_inventory_sha256 != statement_inventory_sha256 {
        return Err(format!(
            "compiled Lean statement inventory is not explicitly reviewed: manifest binds {}, compiled audit is {statement_inventory_sha256}; review the complete audit, change statement_review, and set statement_inventory_sha256 explicitly before update",
            manifest.statement_inventory_sha256
        ));
    }

    if update {
        synchronize_formal_assurance_manifest(
            formal_root,
            &manifest_path,
            &mut manifest,
            &audit,
            &toolchain_lock_digest,
        )?;
    }

    let allowed_axioms: BTreeSet<_> = manifest.allowed_axioms.iter().cloned().collect();
    if allowed_axioms.len() != manifest.allowed_axioms.len() || allowed_axioms.contains("sorryAx") {
        return Err("formal assurance axiom allowlist is duplicate or permits sorryAx".to_owned());
    }

    let mut compiled = BTreeMap::new();
    for declaration in audit.declarations {
        let name = declaration.name.clone();
        if compiled.insert(name.clone(), declaration).is_some() {
            return Err(format!(
                "compiled Lean assurance audit repeated declaration {name}"
            ));
        }
    }
    let expected_source_closure = semantic_source_closure_paths(formal_root)?;
    let expected_closure_digest = semantic_source_closure_digest(&expected_source_closure)?;
    validate_manifest_source_closure(
        &manifest,
        &expected_source_closure,
        &expected_closure_digest,
    )?;
    let mut reviewed = BTreeSet::new();
    let mut claim_ids = BTreeSet::new();
    for claim in &manifest.claims {
        if !claim_ids.insert(claim.claim_id.clone()) {
            return Err(format!(
                "formal assurance manifest repeated claim id {}",
                claim.claim_id
            ));
        }
        if !reviewed.insert(claim.lean_declaration.clone()) {
            return Err(format!(
                "formal assurance manifest repeated declaration {}",
                claim.lean_declaration
            ));
        }
        for (field, value) in [
            ("claim_id", claim.claim_id.as_str()),
            ("claim_text", claim.claim_text.as_str()),
            ("formal_review", claim.formal_review.as_str()),
            ("scope", claim.scope.as_str()),
        ] {
            if value.trim().is_empty() {
                return Err(format!(
                    "formal claim {} has empty {field}",
                    claim.lean_declaration
                ));
            }
        }
        if claim.formal_review != manifest.statement_review {
            return Err(format!(
                "formal claim {} review tag does not match reviewed statement batch {}",
                claim.lean_declaration, manifest.statement_review
            ));
        }
        if !matches!(
            claim.claim_status.as_str(),
            "proved" | "qualified" | "assumed"
        ) {
            return Err(format!(
                "formal claim {} has unsupported status {}",
                claim.lean_declaration, claim.claim_status
            ));
        }
        if let Some((metadata, translation_artifact)) =
            qualified_refinement_metadata(&claim.lean_declaration)
        {
            let expected_symbols = metadata
                .rust_symbols
                .iter()
                .map(|symbol| (*symbol).to_owned())
                .collect::<Vec<_>>();
            let expected_residual = metadata
                .residual_assumptions
                .iter()
                .map(|assumption| (*assumption).to_owned())
                .collect::<Vec<_>>();
            if claim.claim_status != "qualified"
                || claim.claim_text != metadata.claim_text
                || claim.rust_symbols != expected_symbols
                || claim.scope != metadata.scope
                || claim.residual_assumptions != expected_residual
            {
                return Err(format!(
                    "formal claim {} production refinement metadata drifted from the executable boundary table",
                    claim.lean_declaration
                ));
            }
            validate_production_evidence(
                &claim.lean_declaration,
                &claim.evidence,
                metadata.translation_evidence_kind,
                translation_artifact,
            )?;
        }
        if claim.toolchain_lock_sha256 != toolchain_lock_digest {
            return Err(format!(
                "formal claim {} has stale toolchain lock digest",
                claim.lean_declaration
            ));
        }
        if claim.evidence.is_empty() || claim.residual_assumptions.is_empty() {
            return Err(format!(
                "formal claim {} must declare evidence and residual assumptions",
                claim.lean_declaration
            ));
        }
        for symbol in &claim.rust_symbols {
            if symbol.trim().is_empty() {
                return Err(format!(
                    "formal claim {} contains an empty Rust symbol",
                    claim.lean_declaration
                ));
            }
        }
        let expected_proof =
            declaration_source_path(compiled.get(&claim.lean_declaration).ok_or_else(|| {
                format!(
                    "reviewed Lean declaration {} is absent from the compiled environment",
                    claim.lean_declaration
                )
            })?)?;
        let primary = claim
            .evidence
            .iter()
            .filter(|item| {
                matches!(
                    item.kind,
                    FormalEvidenceKind::LeanProof | FormalEvidenceKind::LeanRefinement
                )
            })
            .collect::<Vec<_>>();
        if primary.len() != 1 || primary[0].artifact != expected_proof {
            return Err(format!(
                "formal claim {} must cite exactly its defining Lean module {expected_proof} as primary proof evidence",
                claim.lean_declaration
            ));
        }
        for item in &claim.evidence {
            if item.artifact.trim().is_empty() || !item.kind.validates_path(&item.artifact) {
                return Err(format!(
                    "formal claim {} contains incomplete or kind/path-mismatched evidence {}",
                    claim.lean_declaration, item.artifact
                ));
            }
            let artifact = validated_evidence_path(&item.artifact)?;
            validate_mutation_witnesses(&artifact, &compiled)?;
            validate_sha256(&item.sha256).map_err(|error| {
                format!(
                    "formal claim {} evidence {} has {error}",
                    claim.lean_declaration, item.artifact
                )
            })?;
            let bytes = fs::read(&artifact).map_err(|error| {
                format!("could not read evidence {}: {error}", artifact.display())
            })?;
            let actual = hex::encode(Sha256::digest(&bytes));
            if actual != item.sha256 {
                return Err(format!(
                    "formal claim {} cites evidence {} with digest {}, \
                     but the artifact hashes to {actual}",
                    claim.lean_declaration, item.artifact, item.sha256
                ));
            }
        }

        let declaration = compiled.get(&claim.lean_declaration).ok_or_else(|| {
            format!(
                "reviewed Lean declaration {} is absent from the compiled environment",
                claim.lean_declaration
            )
        })?;
        if declaration.kind != "theorem" {
            return Err(format!(
                "reviewed declaration {} is {}, not theorem",
                claim.lean_declaration, declaration.kind
            ));
        }
        let statement_digest = hex::encode(Sha256::digest(declaration.statement.as_bytes()));
        if statement_digest != claim.lean_statement_sha256 {
            return Err(format!(
                "Lean statement drift for {}: expected {}, found {statement_digest}",
                claim.lean_declaration, claim.lean_statement_sha256
            ));
        }
        let actual_axioms: BTreeSet<_> = declaration.axioms.iter().cloned().collect();
        let reviewed_axioms: BTreeSet<_> = claim.axioms.iter().cloned().collect();
        if actual_axioms != reviewed_axioms {
            return Err(format!(
                "Lean axiom drift for {}: reviewed={reviewed_axioms:?}, compiled={actual_axioms:?}",
                claim.lean_declaration
            ));
        }
        if let Some(unapproved) = actual_axioms.difference(&allowed_axioms).next() {
            return Err(format!(
                "Lean declaration {} transitively depends on unapproved axiom {unapproved}",
                claim.lean_declaration
            ));
        }
    }

    // Every claim references the shared, independently resolved path set.
    // Reject source mutation during the complete claim audit.
    if semantic_source_closure_digest(&expected_source_closure)? != expected_closure_digest {
        return Err("Lean semantic source closure changed during assurance audit".to_owned());
    }
    let compiled_names: BTreeSet<_> = compiled.keys().cloned().collect();
    if reviewed != compiled_names {
        return Err(format!(
            "compiled and reviewed Lean claim inventories differ: reviewed={reviewed:?}, compiled={compiled_names:?}"
        ));
    }
    let evidence_directory = root().join("target/formal");
    fs::create_dir_all(&evidence_directory).map_err(|error| {
        format!(
            "could not create formal evidence directory {}: {error}",
            evidence_directory.display()
        )
    })?;
    let mut evidence = serde_json::to_vec_pretty(
        &serde_json::from_str::<Value>(audit_output.trim())
            .map_err(|error| format!("could not normalize Lean assurance evidence: {error}"))?,
    )
    .map_err(|error| format!("could not encode Lean assurance evidence: {error}"))?;
    evidence.push(b'\n');
    fs::write(
        evidence_directory.join("lean-assurance-audit.json"),
        &evidence,
    )
    .map_err(|error| format!("could not write Lean assurance evidence: {error}"))?;
    let committed_audit = root().join(formal_coverage::AUDIT_PATH);
    if update {
        fs::write(&committed_audit, &evidence)
            .map_err(|error| format!("could not write {}: {error}", committed_audit.display()))?;
    } else if fs::read(&committed_audit).ok().as_deref() != Some(evidence.as_slice()) {
        return Err(format!(
            "{} differs from the compiled Lean assurance audit; run `cargo xtask formal --update`",
            formal_coverage::AUDIT_PATH
        ));
    }
    formal_coverage::synchronize_coverage(&root(), update)?;
    println!("Proof coverage:             committed measurement matches a fresh run");
    println!(
        "Formal assurance audit:     PASS ({} compiled statements; transitive axioms reviewed)",
        reviewed.len()
    );
    Ok(())
}

pub(crate) fn synchronize_formal_assurance_manifest(
    formal_root: &Path,
    manifest_path: &Path,
    manifest: &mut FormalAssuranceManifest,
    audit: &LeanAssuranceAudit,
    toolchain_lock_digest: &str,
) -> Result<(), String> {
    let source_closure = semantic_source_closure_paths(formal_root)?;
    let source_closure_digest = semantic_source_closure_digest(&source_closure)?;
    let mut rich_index = manifest
        .claims
        .iter()
        .filter_map(|claim| claim.claim_id.strip_prefix("AP-FORMAL-RICH-"))
        .filter_map(|suffix| suffix.parse::<usize>().ok())
        .max()
        .unwrap_or(0);
    let mut existing: BTreeMap<_, _> = std::mem::take(&mut manifest.claims)
        .into_iter()
        .map(|claim| (claim.lean_declaration.clone(), claim))
        .collect();
    let mut claims = Vec::with_capacity(audit.declarations.len());
    for declaration in &audit.declarations {
        let statement_digest = hex::encode(Sha256::digest(declaration.statement.as_bytes()));
        let mut claim = if let Some(claim) = existing.remove(&declaration.name) {
            claim
        } else {
            rich_index += 1;
            let short_name = declaration
                .name
                .rsplit('.')
                .next()
                .unwrap_or(&declaration.name);
            let phrase = short_name.replace('_', " ");
            let is_product = declaration.name.starts_with("Auths.Product.");
            let is_gateway = [
                "Auths.Product.Recovery.",
                "Auths.Product.RequestConstruction.",
                "Auths.Product.ArgumentBinding.",
                "Auths.Product.ScalarProjection.",
                "Auths.Product.DecimalProjection.",
                "Auths.Product.FieldProjection.",
                "Auths.Product.PathCompiler.",
                "Auths.Product.BodyCompiler.",
                "Auths.Product.DerivedTokens.",
                "Auths.Product.RecipeBinding.",
                "Auths.Product.ProfileSchema.",
                "Auths.Product.EchoPointer.",
                "Auths.Product.AttemptBinding.",
                "Auths.Product.HeaderCompiler.",
                "Auths.Product.RequestCompiler.",
                "Auths.Product.TemplateMembers.",
                "Auths.Product.TemplateAst.",
                "Auths.Product.SubmitOrder.",
                "Auths.Product.RelativeCeiling.",
            ]
            .iter()
            .any(|prefix| declaration.name.starts_with(prefix));
            let is_lifecycle = declaration.name.starts_with("Auths.Lifecycle.");
            let is_connection = declaration
                .name
                .starts_with("Auths.Product.ConnectionGenerations.");
            FormalAssuranceClaim {
                claim_id: format!("AP-FORMAL-RICH-{rich_index:03}"),
                claim_text: if is_lifecycle {
                    format!("Lean proves the reservation/execution lifecycle property: {phrase}.")
                } else if is_connection {
                    format!("Lean proves the connection credential-generation property: {phrase}.")
                } else if is_gateway {
                    format!("Lean proves the gateway recipe property: {phrase}.")
                } else if is_product {
                    format!("Lean proves the bounded product-policy property: {phrase}.")
                } else {
                    format!("Lean proves the rich authority property: {phrase}.")
                },
                claim_status: "proved".to_owned(),
                lean_declaration: declaration.name.clone(),
                lean_statement_sha256: String::new(),
                formal_review: "rich-authority-refinement-2026-07-29".to_owned(),
                rust_symbols: Vec::new(),
                semantic_source_closure_sha256: String::new(),
                evidence: vec![FormalEvidence {
                    kind: FormalEvidenceKind::LeanProof,
                    artifact: declaration_source_path(declaration)?,
                    sha256: String::new(),
                }],
                scope: if is_lifecycle {
                    "Pure V1 lifecycle transitions, capacity conservation, replay, configuration gates, credential ordering, provider entry, and reconciliation.".to_owned()
                } else if is_connection {
                    "Pure connection-record generation semantics over every sequence of install, join, rotate, disable, enable, and revoke across any number of processes sharing one record: the credential generation, the retained-entry lease rule, and revocation.".to_owned()
                } else if is_gateway {
                    "Pure gateway recipe semantics: the recovery capability a recipe's declarations determine, closed request construction over every compiled plan and argument list, the attempt-record transition rule over every sequence of records, the admission order over every event trace, and the exact relative ceiling.".to_owned()
                } else if is_product {
                    "Pure V1 bounded product-policy commitments, checked arithmetic, configuration gating, and eligibility.".to_owned()
                } else {
                    "Rich target-V1 authority semantics over opaque identity carriers and extensional finite sets.".to_owned()
                },
                residual_assumptions: vec![
                    "Lean's kernel, the pinned toolchain, the listed foundational axioms, and the theorem premises are trusted.".to_owned(),
                ],
                toolchain_lock_sha256: String::new(),
                axioms: Vec::new(),
            }
        };
        claim.lean_statement_sha256 = statement_digest;
        if declaration.name == "Auths.Product.StrictOrder.Refinement.ordered_implies_pairwise"
            || declaration.name
                == "Auths.Product.StrictOrder.Refinement.ordered_implies_no_duplicates"
        {
            claim.claim_text = "The independent adjacent-chain model earns global pairwise ordering and duplicate absence under the displayed primitive relation laws.".to_owned();
            claim.scope = "Every list and Boolean comparison relation with the displayed transitivity/irreflexivity properties. This is a model law; separate source refinement earns the model predicate.".to_owned();
        }

        if declaration.name
            == "Auths.Product.RecordTimes.Refinement.state_change_preserves_valid_time"
            || declaration.name
                == "Auths.Product.RecordTimes.Refinement.data_change_preserves_valid_time"
        {
            claim.claim_text = "The independent record-time model proves that the stated administrative state/time conditions preserve complete lifetime and revocation-timestamp validity.".to_owned();
            claim.scope = "Every natural-number lifetime, optional revocation timestamp and actual state carrier satisfying the displayed independent before-state and administrative conditions. Separate source refinements earn those conditions; this does not claim the whole native caller was translated.".to_owned();
        }

        claim.formal_review.clone_from(&manifest.statement_review);
        if declaration.name == "Auths.Codec.readHead_encodeHead" {
            claim.claim_text = "The independent CBOR head grammar reads every valid shortest head encoding and preserves arbitrary following bytes.".to_owned();
            claim.scope = "The pure natural-number byte model: major tags below eight and arguments below 2^64. This model theorem alone is not a refinement of the shipping encoder or a complete protocol-object codec claim.".to_owned();
        }
        if declaration
            .name
            .starts_with("Auths.Product.CollectionFence.")
        {
            claim.claim_text = format!(
                "The independent collection-fence history model proves {}.",
                declaration
                    .name
                    .rsplit('.')
                    .next()
                    .unwrap_or("the stated property")
            );
            claim.scope = "Arbitrary finite model histories with any number of workers, collection, admission, crashes, recovery, and acknowledgement loss. This is the cutoff invariant, not a proof of the complete counter-admission algorithm or backend/driver correspondence.".to_owned();
        }
        if declaration.name.starts_with("Auths.Product.EntryDeadline.") {
            claim.claim_text = format!(
                "The independent entry-deadline model proves {}.",
                declaration
                    .name
                    .rsplit('.')
                    .next()
                    .unwrap_or("the stated property")
            );
            claim.scope = "Finite lists of independent natural-number upper endpoints, preserving inclusive and exclusive boundaries. This is endpoint algebra; it does not establish that an actual verification or installed gate supplied every required bound.".to_owned();
        }
        if declaration.name.starts_with("Auths.Product.EntryGate.") {
            claim.claim_text = format!(
                "The independent complete entry-time model proves {}.",
                declaration.name.rsplit('.').next().unwrap_or("the stated property")
            );
            claim.scope = "Every represented evaluation/current time, original authority/prepared/current endpoint, optional clock/qualification sample and exact monotonic nanosecond sample. This model result does not establish native bound acquisition, verified-command provenance, credential validity or physical dispatch correspondence.".to_owned();
        }
        if declaration.name.starts_with("Auths.Product.NativeCompiler.")
            && !declaration.name.starts_with("Auths.Product.NativeCompiler.Refinement.")
            && !declaration.name.starts_with("Auths.Product.NativeCompiler.StdModel.")
        {
            claim.claim_text = "The independent original JSON/schema/typed-body, byte-decoding and finite-map models establish the displayed meaning, determinacy, association/order preservation, lookup, parser-fold, count or original-name consequence.".to_owned();
            claim.scope = "Every displayed represented source/kernel tree, original field sequence, finite map or byte column with its explicit range/order/representation conditions. Separate shipping native refinements must earn those model relations and decisions. These model statements alone do not establish raw JSON parsing, actual schema/rule-map acceptance, full compiler/digest/plan provenance, authorization, driver I/O or durable history.".to_owned();
        }
        if declaration.name.starts_with("Auths.Composition.Model.") {
            claim.claim_text = format!(
                "The independent finite child-sequence model proves {}.",
                declaration
                    .name
                    .rsplit('.')
                    .next()
                    .unwrap_or("the stated property")
            );
            claim.scope = "Natural-number counts and minimum diagnostics over arbitrary finite child-outcome lists, with explicit treatment of structural invalidity. This is the independent aggregation specification, not complete plan traversal, registry/stage, callback or verifier soundness.".to_owned();
        }
        if declaration.name.starts_with("Auths.Composition.Examples.") {
            claim.claim_text = format!(
                "A kernel-checked execution of the shipping summary operations establishes the concrete {} witness.",
                declaration.name.rsplit('.').next().unwrap_or("stated")
            );
            claim.scope = "The exact bounded child outcomes and threshold in this statement, including successful, denied and indeterminate cases. The Lean harness calls the actual translated push and finalizer operations; it does not assert plan validation, callback ordering or full verifier acceptance.".to_owned();
            claim.claim_status = "qualified".to_owned();
        }
        if declaration.name == "Auths.Composition.Refinement.saturating_add_exact" {
            claim.claim_text = "The pinned Aeneas unsigned-word saturating-add model equals the minimum of the word maximum and the natural-number sum.".to_owned();
            claim.scope = "Every pair of unsigned machine-word model values on either supported width. This proves a property of the pinned standard-library model; it is not a new opaque Auths algorithm or a complete verifier theorem.".to_owned();
        }
        if declaration
            .name
            .starts_with("auths_composition.alloc.vec.Vec.")
        {
            claim.claim_text = format!(
                "The transparent positive bounded-vector adapter proves {}.",
                declaration
                    .name
                    .rsplit('.')
                    .next()
                    .unwrap_or("the stated identity")
            );
            claim.scope = "Every vector in the pinned usize-bounded carrier. Both conversion round trips, injectivity and exact deref delegation preserve all elements and their order. This is standard-container model equivalence, not an Auths authorization decision.".to_owned();
        }
        if matches!(
            declaration.name.as_str(),
            "Auths.Composition.Work.event_count" | "Auths.Composition.Work.leaf_order"
        ) {
            claim.claim_text = format!(
                "The independent recursive plan model proves {}.",
                declaration
                    .name
                    .rsplit('.')
                    .next()
                    .unwrap_or("the stated property")
            );
            claim.scope = "Every finite independent plan and arbitrary total stateful branch function. Counting events gives the node count; recording proof references gives the exact leaf order. Separate source corollaries establish the shipping evaluator connection under explicit callback contracts.".to_owned();
        }
        if matches!(
            declaration.name.as_str(),
            "Auths.Composition.Bounds.node_bound" | "Auths.Composition.Bounds.bounded_events"
        ) {
            claim.claim_text = format!(
                "The independent nonempty plan model proves {}.",
                declaration
                    .name
                    .rsplit('.')
                    .next()
                    .unwrap_or("the stated bound")
            );
            claim.scope = "All finite plans with no empty compound node. Node count is bounded by depth times leaf count; the explicit depth-16 and 128-leaf premises give 2048 events. This is a structural semantic-event bound, not a complete verifier, callback, allocation or host-stack bound.".to_owned();
        }
        if declaration
            .name
            .starts_with("Auths.Composition.PlanExamples.")
        {
            claim.claim_text = format!(
                "A kernel-checked execution of the complete shipping inner plan evaluator establishes the {} witness.",
                declaration.name.rsplit('.').next().unwrap_or("stated")
            );
            claim.scope = "The concrete represented two- or three-leaf plan and explicit stateful callbacks in this statement, including exact outcomes, callback counts and post-order events for all/any/k. Native tests mirror the mixed-outcome cases through the public validating wrapper. This is not a complete proof or cryptographic acceptance witness.".to_owned();
            claim.claim_status = "qualified".to_owned();
            claim.rust_symbols = vec!["auths_composition::evaluate_node".to_owned()];
            claim.evidence.retain(|item| {
                !matches!(
                    item.kind,
                    FormalEvidenceKind::MechanicalTranslation | FormalEvidenceKind::SourceClosure
                )
            });
            claim.evidence.push(FormalEvidence {
                kind: FormalEvidenceKind::MechanicalTranslation,
                artifact: COMPOSITION_TRANSLATION.to_owned(),
                sha256: String::new(),
            });
            claim.evidence.push(FormalEvidence {
                kind: FormalEvidenceKind::SourceClosure,
                artifact: "formal/qualification/aeneas/source-closure.json".to_owned(),
                sha256: String::new(),
            });
        }
        if [
            "Auths.Composition.ValidationCapacity.",
            "Auths.Composition.ValidationProgress.",
            "Auths.Composition.ValidationShape.",
            "Auths.Composition.ValidationComplete.",
            "Auths.Composition.ValidationSoundness.",
        ]
        .iter()
        .any(|prefix| declaration.name.starts_with(prefix))
        {
            claim.claim_text = format!(
                "The independent structural plan model proves {}.",
                declaration
                    .name
                    .rsplit('.')
                    .next()
                    .unwrap_or("the stated property")
            );
            claim.scope = "Arbitrary finite independent plans and natural limits. The validity relation is stated independently as operator/width/depth validity and distinct bounded leaves. The checker is proved sound and complete for it; progress preserves the exact set and forbids reuse. Separate public-source refinements discharge the shipping validation bridge. These are structural results, not full leaf-proof authorization or complete verifier work bounds.".to_owned();
        }
        if declaration.name.starts_with("Auths.Composition.SetModel.")
            || declaration.name == "Auths.Composition.Collect.push_exact"
            || declaration.name == "Auths.Composition.ValidationLeaves.word_max_exact"
            || declaration.name == "Auths.Composition.Order.reference_key_injective"
        {
            claim.claim_text = format!(
                "The reviewed standard-container model proves {}.",
                declaration
                    .name
                    .rsplit('.')
                    .next()
                    .unwrap_or("the stated identity")
            );
            claim.scope = "The displayed bounded sequence/set carrier, capacity and lawful-order premises. These lemmas prove exact semantic properties of the transparent container and numeric models. They do not prove Rust standard-library allocation, balancing, runtime cost or host behavior; the compiled source bridge lists that library boundary explicitly.".to_owned();
        }
        if declaration
            .name
            .starts_with("Auths.Composition.ValidationExamples.")
        {
            claim.claim_text = format!(
                "The independent structural validity contract establishes the concrete {} witness.",
                declaration.name.rsplit('.').next().unwrap_or("stated")
            );
            claim.scope = "The exact finite plan and limits in the statement. Model validity/refusal lemmas support separately qualified public-source execution witnesses; no leaf-proof or cryptographic authority claim follows from structural validity alone.".to_owned();
        }
        if declaration.name.starts_with("Auths.Crypto.Encoding.") {
            claim.claim_text = format!(
                "The independent numeric encoding model proves {}.",
                declaration
                    .name
                    .rsplit('.')
                    .next()
                    .unwrap_or("the stated property")
            );
            claim.scope = "The displayed bytes, bounded base-256 digits, natural coordinates and sign propositions. These transparent arithmetic/representation lemmas support the separately qualified shipping encoding guards. No curve recovery, signature equation, primitive-security or complete-verifier claim follows from this helper statement.".to_owned();
        }
        if declaration.name.starts_with("Auths.Support.UnitCallback.") {
            claim.claim_text = format!(
                "The transparent unit-output ABI adapter proves {}.",
                declaration
                    .name
                    .rsplit('.')
                    .next()
                    .unwrap_or("the stated round trip")
            );
            claim.scope = "Every typed Result value, including failure, divergence and success, with arbitrary state. Erasing and restoring the unit output are mutual inverses. This is a representation theorem, not a substitute callback algorithm or an authorization claim.".to_owned();
        }
        if [
            "Auths.Crypto.ByteLex.",
            "Auths.Crypto.CoordinateModel.",
            "Auths.Crypto.LowContract.half_order_exact",
            "Auths.Crypto.WeakContract.zero_value",
            "Auths.Crypto.WeakContract.one_value",
            "Auths.Crypto.WeakContract.minus_one_value",
            "Auths.Crypto.WeakContract.order_eight_a_value",
            "Auths.Crypto.WeakContract.order_eight_b_value",
            "Auths.Crypto.Strict.Acceptance.",
        ]
        .iter()
        .any(|prefix| declaration.name.starts_with(prefix))
        {
            claim.claim_text = format!(
                "The independent numeric/relational signature model proves {}.",
                declaration
                    .name
                    .rsplit('.')
                    .next()
                    .unwrap_or("the displayed property")
            );
            claim.scope = "The displayed bounded bytes or arbitrary finite byte lists and explicit primitive specification functions. Byte order equals unsigned numeric order at equal width; constants have the declared values; accepted-input relations are independent of source success and characterize the transparent model in both directions. This is model/representation evidence, not cryptographic primitive correctness, native adapter binding, full dispatch or complete E5 assurance.".to_owned();
        }
        if declaration.name == "Auths.StatusSelection.Search.search_loop" {
            claim.claim_text = "The transparent pinned standard-search model terminates on a positive, bounded sorted interval with sufficient fuel; its exact success Boolean is target membership in that interval and its returned index stays within the interval endpoint.".to_owned();
            claim.scope = "Reviewed standard-library model proof for arbitrary finite String lists under a genuine ordering invariant, index bounds and sufficient fuel. It proves no Rust standard-library machine code or sorting constructor. Actual Auths contains/visibility/port source binding is earned by separate audited statements; evidence authenticity, constructor validity and complete E2/M6 remain open.".to_owned();
        }
        if declaration.name == "Auths.StatusSelection.Algebra.evaluateScan_eq_evaluate" {
            claim.claim_text = "For every finite input, subject equality operation, view and policy, the operational accumulator equals the independent filter/max/tie-set status specification, including the complete decision and horizon.".to_owned();
            claim.scope = "Pure semantic equivalence without an input-validity or desired-result premise. The proof uses attained maxima, complete tie sets, associative record combination and exact minimum horizons. This module imports no generated Rust. Native source binding is earned only by separately audited port statements; anchor-view source correspondence, evidence authenticity and full E2/M6 remain open.".to_owned();
        }
        if [
            "Auths.StatusSelection.byte_array_comparison",
            "Auths.StatusSelection.native_floor_view",
            "Auths.StatusSelection.unknown_issuer_visible",
            "AuthsStatusSelection.lt_default_delegates",
            "AuthsStatusSelection.gt_default_delegates",
            "AuthsStatusSelection.max_default_delegates",
        ]
        .contains(&declaration.name.as_str())
        {
            claim.claim_text = "The displayed independent issuer-visibility law, exact first-rule representation bridge, standard byte-array model or unconditional dictionary projection holds.".to_owned();
            claim.scope = "Only the displayed model or representation/standard-interface statement. The semantic visibility model has no generated-Rust import. These are not proofs of signature authenticity, complete selector/filter-max equivalence, anchor selection, constructor validity or full E2/M6.".to_owned();
        }
        if [
            "Auths.TemporalWitness.assurance_permits_iff",
            "Auths.TemporalWitness.successful_horizon_bounded",
            "AuthsTemporalWitness.lt_default_delegates",
            "Auths.TemporalWitness.Examples.selected_expiry_admitted",
            "Auths.TemporalWitness.Examples.missing_requirement_refused",
            "Auths.TemporalWitness.Examples.missing_observation_refused",
            "Auths.TemporalWitness.Examples.unbounded_requirement_needs_no_observation",
            "Auths.TemporalWitness.Examples.overflowing_expiry_saturates",
        ]
        .contains(&declaration.name.as_str())
        {
            claim.claim_text = "The independent expiry/status model or exact standard dictionary bridge proves the displayed property or boundary witness.".to_owned();
            claim.scope = "Only the displayed independent finite-list expiry semantics, explicit status-result algebra, numeric examples or unconditional partial_cmp delegation. The model has no generated-Rust import. Pure model witnesses are not claimed as native executions; native parity separately uses actual validated Rust constructors. Evidence selection, full verification and runtime consumption remain open.".to_owned();
        }
        if [
            "AuthsSuiteAdapters.ed_error_to_from",
            "AuthsSuiteAdapters.ed_error_from_to",
            "AuthsSuiteAdapters.p256_error_to_from",
            "AuthsSuiteAdapters.p256_error_from_to",
            "AuthsSuiteAdapters.ed25519_delegates",
            "AuthsSuiteAdapters.p256_delegates",
        ]
        .contains(&declaration.name.as_str())
        {
            claim.claim_text = "The compiled suite component bridge proves exact delegation or a complete error-constructor isomorphism.".to_owned();
            claim.scope = "Exactly the displayed owning function, importing binding and exhaustive three-constructor error conversions. Delegation is unconditional apart from the explicit foreign implementation parameter; the native owning algorithms remain transparent and separately proved. These bridge results introduce no assumed Auths algorithm, primitive law, constructor/registry validity or complete E5 claim.".to_owned();
        }
        if declaration.name == "Auths.Crypto.NativeExamples.forwarding_contract"
            || declaration.name == "Auths.Crypto.P256Examples.forwarding_contract"
        {
            claim.claim_text = "The explicitly supplied forwarding mock satisfies its stated call-binding contracts.".to_owned();
            claim.scope = "Only the displayed mock implementation, decoder, signature representation and message/signature equality predicate. This is an inhabited-contract witness; it makes no claim that any cryptographic library is correct or that any signature is authentic.".to_owned();
        }
        if [
            "Auths.Crypto.BufferAllocation.signed_bounds_iff",
            "Auths.Crypto.CommitmentFrames.application_length",
            "Auths.Crypto.CommitmentFrames.identifier_length",
            "Auths.Crypto.CommitmentFrames.application_unambiguous",
            "Auths.Crypto.CommitmentFrames.identifier_unambiguous",
            "Auths.Crypto.CommitmentFrames.application_identifier_separate",
            "Auths.Crypto.CommitmentFrames.signing_application_separate",
            "Auths.Crypto.CommitmentFrames.signing_identifier_separate",
            "Auths.Crypto.CommitmentRefinement.identifier_tag_word",
            "Auths.Crypto.Sha256Examples.forwarding_contract",
        ]
        .contains(&declaration.name.as_str())
        {
            claim.claim_text = format!(
                "The independent commitment/representation model proves {}.",
                declaration
                    .name
                    .rsplit('.')
                    .next()
                    .unwrap_or("the displayed property")
            );
            claim.scope = "Exactly the displayed finite byte lists, valid frame relations, scalar representation or explicit mock contract. Length framing binds equal inputs at the byte level and separates signing/application/identifier domains. This is model/representation evidence; it does not establish hash injectivity, cryptographic security, native library correctness, caller integration or complete E5.".to_owned();
        }
        let proof_kind = if declaration.module.contains(".Refinement") {
            FormalEvidenceKind::LeanRefinement
        } else {
            FormalEvidenceKind::LeanProof
        };
        claim.evidence.retain(|item| {
            !matches!(
                item.kind,
                FormalEvidenceKind::LeanProof | FormalEvidenceKind::LeanRefinement
            )
        });
        claim.evidence.insert(
            0,
            FormalEvidence {
                kind: proof_kind,
                artifact: declaration_source_path(declaration)?,
                sha256: String::new(),
            },
        );
        claim
            .semantic_source_closure_sha256
            .clone_from(&source_closure_digest);
        claim.toolchain_lock_sha256 = toolchain_lock_digest.to_owned();
        claim.axioms.clone_from(&declaration.axioms);
        if let Some((rust_symbol, property)) = lifecycle_refinement_metadata(&declaration.name) {
            claim.claim_text = format!(
                "Lean proves the mechanically translated shipping Rust lifecycle kernel refines the rich semantics for {property}."
            );
            claim.rust_symbols = vec![rust_symbol.to_owned()];
            claim.evidence = vec![FormalEvidence {
                kind: FormalEvidenceKind::LeanRefinement,
                artifact: "formal/Auths/Lifecycle/Refinement.lean".to_owned(),
                sha256: String::new(),
            }];
            claim.scope = format!(
                "The pinned Charon/Aeneas translation of `{rust_symbol}` is extensionally equivalent to the corresponding rich Lean V1 lifecycle semantics."
            );
            claim.residual_assumptions = vec![
                "Lean's kernel, the pinned Rust/Charon/Aeneas/Lean toolchain, the qualified translation boundary, the listed foundational axioms, and the theorem premises are trusted.".to_owned(),
            ];
        }
        if let Some((metadata, translation_artifact)) =
            qualified_refinement_metadata(&declaration.name)
        {
            claim.claim_text = metadata.claim_text.to_owned();
            claim.claim_status = "qualified".to_owned();
            claim.rust_symbols = metadata
                .rust_symbols
                .iter()
                .map(|symbol| (*symbol).to_owned())
                .collect();
            claim.scope = metadata.scope.to_owned();
            claim.residual_assumptions = metadata
                .residual_assumptions
                .iter()
                .map(|assumption| (*assumption).to_owned())
                .collect();
            claim.evidence.retain(|item| {
                !matches!(
                    item.kind,
                    FormalEvidenceKind::SourceClosure
                        | FormalEvidenceKind::MechanicalTranslation
                        | FormalEvidenceKind::TranslatedRust
                )
            });
            claim.evidence.push(FormalEvidence {
                kind: metadata.translation_evidence_kind,
                artifact: translation_artifact.to_owned(),
                sha256: String::new(),
            });
            claim.evidence.push(FormalEvidence {
                kind: FormalEvidenceKind::SourceClosure,
                artifact: "formal/qualification/aeneas/source-closure.json".to_owned(),
                sha256: String::new(),
            });
        }
        claims.push(claim);
    }
    if !existing.is_empty() {
        return Err(format!(
            "formal assurance update refuses to auto-retire reviewed declarations absent from the compiled inventory: {:?}; remove each claim explicitly in the reviewed change",
            existing.keys().collect::<Vec<_>>()
        ));
    }
    manifest.semantic_source_closure = FormalSemanticSourceClosure {
        sha256: source_closure_digest,
        paths: source_closure,
    };
    manifest.claims = claims;
    // Refresh every evidence digest before rendering.
    //
    // Some cited artifacts are REGENERATED by the same command that validates
    // them -- `source-closure.json` most obviously -- so a digest recorded
    // before regeneration is stale by construction. Recomputing here is what
    // makes the binding maintainable rather than a standing false alarm; the
    // non-update path still verifies and refuses a mismatch.
    for claim in &mut manifest.claims {
        for item in &mut claim.evidence {
            let artifact = validated_evidence_path(&item.artifact)?;
            let bytes = fs::read(&artifact).map_err(|error| {
                format!("could not read evidence {}: {error}", artifact.display())
            })?;
            item.sha256 = hex::encode(Sha256::digest(&bytes));
        }
    }
    let rendered = toml::to_string_pretty(manifest)
        .map_err(|error| format!("could not render formal assurance manifest: {error}"))?;
    fs::write(manifest_path, format!("{}\n", rendered.trim_end()))
        .map_err(|error| format!("could not write {}: {error}", manifest_path.display()))?;
    println!(
        "Formal assurance update:    {} compiled claims synchronized",
        manifest.claims.len()
    );
    Ok(())
}

fn declaration_source_path(declaration: &LeanAssuranceDeclaration) -> Result<String, String> {
    if declaration.module.trim().is_empty()
        || !declaration.module.split('.').all(|part| {
            !part.is_empty()
                && part
                    .bytes()
                    .all(|byte| byte.is_ascii_alphanumeric() || byte == b'_')
        })
    {
        return Err(format!(
            "compiled Lean declaration {} has invalid defining module {}",
            declaration.name, declaration.module
        ));
    }
    let path = format!("formal/{}.lean", declaration.module.replace('.', "/"));
    if !root().join(&path).is_file() {
        return Err(format!(
            "compiled Lean declaration {} defining module is not a repository file: {path}",
            declaration.name
        ));
    }
    Ok(path)
}

/// Computes the repository-local transitive Lean import closure from the exact
/// module compiled by the assurance audit. This replaces a hand-maintained list
/// which had omitted mutation proofs and reviewed/generated external bridges.
fn semantic_source_closure_paths(formal_root: &Path) -> Result<Vec<String>, String> {
    validate_lake_dependency_worktrees(formal_root)?;
    let workspace_root = root();
    let entry = formal_root.join("Auths/AssuranceAudit.lean");
    let output = command_output_in(
        "lake",
        &[
            "env",
            "lean",
            "--run",
            "tools/SourceClosure.lean",
            &formal_root.display().to_string(),
            &entry.display().to_string(),
        ],
        formal_root,
        None,
    )?;
    let dependencies: Vec<String> = serde_json::from_str(output.trim())
        .map_err(|error| format!("invalid pinned-Lean source closure: {error}"))?;
    let mut visited = BTreeSet::new();
    for dependency in dependencies {
        let path = fs::canonicalize(&dependency)
            .map_err(|error| format!("could not resolve Lean dependency {dependency}: {error}"))?;
        if !is_repository_lean_dependency(formal_root, &path) {
            return Err(format!(
                "pinned-Lean source closure contains a non-repository source: {dependency}"
            ));
        }
        let relative = path
            .strip_prefix(&workspace_root)
            .map_err(|error| format!("Lean source escaped workspace: {error}"))?
            .to_string_lossy()
            .replace('\\', "/");
        if !visited.insert(relative) {
            return Err(format!(
                "pinned-Lean source closure repeats source {dependency}"
            ));
        }
    }
    if !visited.contains("formal/Auths/AssuranceAudit.lean") {
        return Err("pinned-Lean source closure omits the assurance audit root".to_owned());
    }
    for relative in [
        "formal/tools/SourceClosure.lean",
        "formal/algebra-contract-v1.toml",
        "formal/lakefile.toml",
        "formal/lake-manifest.json",
        "formal/lean-toolchain",
    ] {
        let path = workspace_root.join(relative);
        let metadata = fs::symlink_metadata(&path)
            .map_err(|error| format!("could not stat Lean closure input {relative}: {error}"))?;
        if !metadata.file_type().is_file() || metadata.file_type().is_symlink() {
            return Err(format!(
                "Lean closure input is not a regular non-symlink file: {relative}"
            ));
        }
        visited.insert(relative.to_owned());
    }
    Ok(visited.into_iter().collect())
}

fn validate_lake_dependency_worktrees(formal_root: &Path) -> Result<(), String> {
    let manifest_path = formal_root.join("lake-manifest.json");
    let manifest: Value = serde_json::from_slice(
        &fs::read(&manifest_path)
            .map_err(|error| format!("could not read {}: {error}", manifest_path.display()))?,
    )
    .map_err(|error| format!("invalid {}: {error}", manifest_path.display()))?;
    let packages_dir = manifest["packagesDir"]
        .as_str()
        .ok_or("Lake manifest omits packagesDir")?;
    let packages = manifest["packages"]
        .as_array()
        .ok_or("Lake manifest omits packages")?;
    for package in packages {
        if package["type"].as_str() != Some("git") {
            continue;
        }
        let name = package["name"]
            .as_str()
            .ok_or("Lake git package omits name")?;
        let expected_rev = package["rev"]
            .as_str()
            .ok_or_else(|| format!("Lake git package {name} omits rev"))?;
        let directory = formal_root.join(packages_dir).join(name);
        let head = command_output_in("git", &["rev-parse", "HEAD"], &directory, None)?;
        let status = command_output_in("git", &["status", "--porcelain=v1"], &directory, None)?;
        validate_lake_package_state(name, expected_rev, head.trim(), status.trim())?;
    }
    Ok(())
}

fn validate_lake_package_state(
    name: &str,
    expected_rev: &str,
    head: &str,
    status: &str,
) -> Result<(), String> {
    if head != expected_rev {
        return Err(format!(
            "Lake dependency {name} is at {head}, expected manifest rev {expected_rev}"
        ));
    }
    if !status.is_empty() {
        return Err(format!(
            "Lake dependency {name} has local modifications; assurance refuses a dirty proof dependency"
        ));
    }
    Ok(())
}

fn is_repository_lean_dependency(formal_root: &Path, candidate: &Path) -> bool {
    candidate.starts_with(formal_root)
        && !candidate.starts_with(formal_root.join(".lake"))
        && candidate.extension().is_some_and(|ext| ext == "lean")
}

fn lifecycle_refinement_metadata(declaration: &str) -> Option<(&'static str, &'static str)> {
    match declaration {
        "Auths.Lifecycle.Refinement.translated_terminal_refines_rich" => Some((
            "auths_lifecycle::model::LifecycleState::is_terminal",
            "terminal-state classification",
        )),
        "Auths.Lifecycle.Refinement.translated_transition_refines_rich" => Some((
            "auths_lifecycle::kernel::transition_code",
            "state transitions and their authorization gates",
        )),
        "Auths.Lifecycle.Refinement.translated_exclusive_capacity_refines_rich" => Some((
            "auths_lifecycle::kernel::exclusive_capacity_available",
            "exclusive capacity",
        )),
        "Auths.Lifecycle.Refinement.translated_additive_capacity_refines_rich" => Some((
            "auths_lifecycle::kernel::additive_capacity_available",
            "checked additive capacity",
        )),
        "Auths.Lifecycle.Refinement.translated_replay_refines_rich" => Some((
            "auths_lifecycle::kernel::replay_code",
            "replay classification",
        )),
        _ => None,
    }
}

struct ProductionRefinementMetadata {
    claim_text: &'static str,
    rust_symbols: &'static [&'static str],
    scope: &'static str,
    residual_assumptions: &'static [&'static str],
    translation_evidence_kind: FormalEvidenceKind,
}

